export const meta = {
  name: 'record-clarity',
  description: 'Clarity pass over record entries, POSITIONS or FACTS: per chunk, for FACTS an assessment first, then the stream\'s headless Opus writer, a cold read, a check, the writer\'s fix round, a second cold read and a judge; nothing applied',
  phases: [
    { title: 'Assess', detail: 'FACTS only: the rubric over every entry, a disposition each', model: 'opus' },
    { title: 'Write', detail: 'one writer per chunk, the standing brief and writer.md', model: 'opus' },
    { title: 'ColdRead', detail: 'a reader with only the worker skill', model: 'opus' },
    { title: 'Check', detail: 'fidelity against the sources, and the reader against the meaning', model: 'opus' },
    { title: 'Fix', detail: 'the writer\'s second round', model: 'opus' },
    { title: 'Reread', detail: 'a second cold read of the fixed entries', model: 'opus' },
    { title: 'Judge', detail: 'apply or hold each entry, once', model: 'opus' },
  ],
}

// args: { kind: 'positions' | 'facts', out: '/abs/folder/', chunks: [{ name: 'c1', entries: ['P-7', 'P-8'] }],
//         stream: 'name' (the writer stream, default the first chunk's name), from: 'judge' (only judge chunks already written) }
// The writer and its fix round run in the stream's headless Opus session (writer-stream.sh), driven by a
// Sonnet step that only runs the command and waits; the stream resumes its session while the context is small.
// Every agent writes its own files into out + chunk name + '/'. The judge writes final.apply and queue.md;
// the coordinator applies final.apply with record.py, files queue.md and commits. Nothing here touches the record.
const T = '/home/user/fortress/explorations/coordinator/tools/record-clarity/'
const KIND = args.kind
const OUT = args.out
const cut = (s, n) => (s ? String(s).slice(0, n) : null)
const ASSESS = {
  type: 'object',
  properties: { rewrite: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' } },
  required: ['rewrite', 'summary'],
}
const STREAM = args.stream || args.chunks[0].name
const FROM = args.from || 'assess'
const drive = (x, n, brief) => {
  const task = `Read your brief and follow it: ${T}${brief}. Your kind: ${KIND}. Your chunk: ${x.name}. Your entries: ${x.write.join(', ')}. Your folder: ${x.dir}`
  const log = `${x.dir}writer-${n}.log`, done = `${x.dir}writer-${n}.done`
  return agent(`You drive a long command and report its output; you judge nothing and write nothing else. The folder ${x.dir} may not exist yet: create it with mkdir -p.
1. If ${done} exists, skip to step 3.
2. Run this in the background with the Bash tool's run_in_background, exactly:
   ${T}writer-stream.sh ${STREAM} "${task}" > ${log} 2>&1; touch ${done}
3. Run \`python3 ${T}wait.py ${done} 540\` in the foreground, with a timeout of 600000 ms. If it exits 1, run it again; repeat until it exits 0.
4. Your final message: the last 60 lines of ${log}, verbatim.`, { label: `${n === 1 ? 'write' : 'fix'} ${x.name}`, phase: n === 1 ? 'Write' : 'Fix', model: 'sonnet' })
}
const tell = (x, extra) => `Your kind: ${KIND}. Your chunk: ${x.name}. Your entries: ${x.write.join(', ')}. Your folder: ${x.dir}` + (extra ? '\n' + extra : '')

const res = await pipeline(args.chunks,
  async (c) => {
    const dir = OUT + c.name + '/'
    if (FROM === 'judge') return { name: c.name, dir, write: c.entries, judgeOnly: true }
    if (KIND !== 'facts') return { name: c.name, dir, write: c.entries }
    const a = await agent(`Read your brief and follow it: ${T}assess.md\n\nYour chunk: ${c.name}. Its entries: ${c.entries.join(', ')}. Your folder: ${dir}`,
      { label: `assess ${c.name}`, phase: 'Assess', model: 'opus', schema: ASSESS })
    return { name: c.name, dir, write: a ? a.rewrite : [], assess: a ? cut(a.summary, 1200) : 'assessment failed' }
  },
  async (x) => {
    if (!x.write.length) return { ...x, skipped: 'nothing to rewrite' }
    if (x.judgeOnly) return x
    const w = await drive(x, 1, 'writer.md')
    return { ...x, writer: cut(w, 1500) }
  },
  async (x) => {
    if (x.skipped || x.judgeOnly) return x
    const r = await agent(`Read your brief and follow it: ${T}coldread.md\n\nThe file to read: ${x.dir}clean.txt\nYour report: ${x.dir}cold-read.md`,
      { label: `cold read ${x.name}`, phase: 'ColdRead', model: 'opus' })
    return { ...x, coldread: cut(r, 1000) }
  },
  async (x) => {
    if (x.skipped || x.judgeOnly) return x
    const r = await agent(`Read your brief and follow it: ${T}check.md\n\n` + tell(x),
      { label: `check ${x.name}`, phase: 'Check', model: 'opus' })
    return { ...x, check: cut(r, 1500) }
  },
  async (x) => {
    if (x.skipped || x.judgeOnly) return x
    const r = await drive(x, 2, 'fix.md')
    return { ...x, fix: cut(r, 1500) }
  },
  async (x) => {
    if (x.skipped || x.judgeOnly) return x
    const r = await agent(`Read your brief and follow it: ${T}coldread.md\n\nThe file to read: ${x.dir}clean.txt\nYour report: ${x.dir}cold-read-2.md`,
      { label: `reread ${x.name}`, phase: 'Reread', model: 'opus' })
    return { ...x, reread: cut(r, 1000) }
  },
  async (x) => {
    if (x.skipped) return x
    const r = await agent(`Read your brief and follow it: ${T}judge.md\n\n` + tell(x),
      { label: `judge ${x.name}`, phase: 'Judge', model: 'opus' })
    return { ...x, judge: cut(r, 1200) }
  },
)
return res

export const meta = {
  name: 'record-landing',
  description: 'The record brought in line with a landed batch, in a worktree of its own: the evidence script and an Opus sort by home and weight; the entries and routing writers as two headless Opus streams with the mechanical checks; a checker and a cold read; one fix round; a judge who applies or holds each change once, makes two commits on the branch and writes diff.md; then, past the judge\'s checks, the commits landed on main and pushed, the worktree and branch removed, and the orientation update run as a child workflow on the entries the landing changed; then the skill writer installs w
  phases: [
    { title: 'Sort', detail: 'prepare.sh makes the worktree and the evidence; the sorter writes owed.md, one line per change', model: 'opus' },
    { title: 'Write', detail: 'a Sonnet driver starts the entries and routing writers, two headless Opus streams, then checks.sh 1', model: 'sonnet' },
    { title: 'Check', detail: 'the checker and the clarity cold reader, side by side', model: 'opus' },
    { title: 'Fix', detail: 'both writers once more, in the same streams, then checks.sh 2', model: 'sonnet' },
    { title: 'Judge', detail: 'apply or hold each change once; final.sh checks and commits twice on the branch; diff.md', model: 'opus' },
    { title: 'Land', detail: 'the two commits onto main (a fast-forward, or a cherry-pick if main moved), the checks on main, the three pushes, the worktree and branch removed; then the orientation update, a child workflow', model: 'sonnet' },
    { title: 'Skills', detail: 'skills.sh writes the task from the landed diff.md and the orientation judgement; the skill writer, a headless Opus session, installs and edits fortress-repo and commits on main', model: 'sonnet' },
    { title: 'Cold read', detail: 'the changed parts read as a worker new to the repository', model: 'opus' },
    { title: 'Fixes', detail: 'the same writer fixes the cold read\'s flags and commits', model: 'sonnet' },
    { title: 'Page', detail: 'the page of fortress-repo\'s landed changes updated and published by its URL', model: 'opus' },
    { title: 'Push', detail: 'the run\'s folders committed, then the three pushes; the one line for the coordinator', model: 'sonnet' },
    { title: 'Revival page', detail: 'update.py rewrites the page\'s "Where it stands" and its chart; the files it names committed and pushed; the page republished by its URL', model: 'sonnet' },
  ],
}

// Temporary, for the week of the Fable 5.2 launch offer (the curator's order of 2026-11-10): every agent runs
// on Fable, at medium effort where it ran on Opus and at low effort where it ran on Sonnet. The phases above keep
// each role's usual tier. Set FABLE_WEEK to false to go back.
const FABLE_WEEK = false
const OPUS = FABLE_WEEK ? { model: 'fable', effort: 'medium' } : { model: 'opus' }
const SONNET = FABLE_WEEK ? { model: 'fable', effort: 'low' } : { model: 'sonnet' }

// args: { batch: '24', base: 'b0f6cd6b7', landing: '25238e60c', at: '43cd61b62' }
//   batch, the climb batch's number; base, its base; landing, its landing commit; at, for a replay only, the commit
//   that the worktree is made at (without it, main's head at the launch).
// The rest follows from them. The worktree /home/user/fortress-landing-N on the branch record/landing-N, or for a
// replay /home/user/fortress-landing-N-replay on record/landing-N-replay; the run's folder in it,
// explorations/compile-ladder/climb-batch-N/record-landing/, as prepare.sh derives it too; the two streams
// landing-N-entries and landing-N-routing, kept in the worktree's tmp/. There is no text argument: a run gives the
// workflow data, never rules of its own. Every agent up to the judge works in the worktree. The judge commits twice
// on the branch; the lander, only when the judge's checks pass, puts the two commits on main, checks main, pushes
// it and removes the worktree and the branch; then the orientation workflow runs in update mode, as a child, on
// the entries the landing changed (README.md, "Landing its result"); then the skill update, its cold read, its
// fixes, the page and the pushes (README.md, "The skill update"); then the revival page's update, its commit, its
// push and its republish (README.md, "The revival page"). A replay lands nothing and runs no update.
const T = '/home/user/fortress/explorations/coordinator/tools/record-landing/'
const RC = '/home/user/fortress/explorations/coordinator/tools/record-clarity/'
if (!args || !args.batch || !args.base || !args.landing) throw new Error('args: { batch, base, landing, at (a replay only) }')
const N = String(args.batch)
const BASE = String(args.base)
const LANDING = String(args.landing)
const AT = args.at ? String(args.at) : 'main'
const TAG = args.at ? N + '-replay' : N
const WT = '/home/user/fortress-landing-' + TAG
const BRANCH = 'record/landing-' + TAG
const RUN = WT + '/explorations/compile-ladder/climb-batch-' + N + '/record-landing/'
const cut = (s, n) => (s ? String(s).slice(0, n) : null)
const where = `Your batch: climb batch ${N}, its base ${BASE}, its landing commit ${LANDING}. Your worktree: ${WT}. The run's folder: ${RUN}`
const SORT = {
  type: 'object',
  properties: {
    counts: { type: 'array', items: { type: 'object', properties: { home: { type: 'string' }, changes: { type: 'integer' } }, required: ['home', 'changes'] } },
    orientation: { type: 'array', items: { type: 'string' } },
    curator: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['counts', 'orientation', 'curator', 'summary'],
}

// One write round: drive.sh starts both streams in the background, waits for both, and runs checks.sh. The
// driver waits in steps of 240 s, under the five minutes that its prompt cache lives, so that no step writes its
// context again; its marker is under the worktree's tmp/, which git ignores.
const MARKS = WT + '/tmp/record-landing/'
const drive = (n) => {
  const log = `${RUN}drive-${n}.log`, done = `${MARKS}drive-${n}.done`
  return agent(`You drive a long command and report its output; you judge nothing and write nothing else.
1. If ${done} exists, skip to step 3.
2. Run this in the background with the Bash tool's run_in_background, exactly:
   mkdir -p ${MARKS}; ${T}drive.sh ${RUN} ${n} > ${log} 2>&1; touch ${done}
3. Run \`python3 ${RC}wait.py ${done} 240\` in the foreground, with a timeout of 270000 ms. If it exits 1, run it again at once; repeat until it exits 0. Each wait stays under five minutes, so that your prompt cache stays warm.
4. Your final message: the last 80 lines of ${log}, verbatim.`, { label: n === 1 ? 'write' : 'fix', phase: n === 1 ? 'Write' : 'Fix', ...SONNET })
}

phase('Sort')
const s = await agent(`Read your brief and follow it: ${T}sort.md\n\n${where}\nFirst run, exactly: ${T}prepare.sh ${N} ${BASE} ${LANDING} ${AT} ${WT} ${BRANCH}`,
  { label: 'sort', phase: 'Sort', ...OPUS, schema: SORT })
if (!s) return { batch: N, worktree: WT, branch: BRANCH, run: RUN, stopped: 'the sort returned nothing: read owed.md in the run folder and the agent transcript before a resume' }
log(`sorted: ${s.counts.map(c => c.home + ' ' + c.changes).join(', ')}`)

phase('Write')
const w1 = await drive(1)

phase('Check')
const checks = await parallel([
  () => agent(`Read your brief and follow it: ${T}check.md\n\n${where}`, { label: 'check', phase: 'Check', ...OPUS }),
  () => agent(`Read your brief and follow it: ${RC}coldread.md\n\nThe file to read: ${RUN}clean.txt\nYour report: ${RUN}cold-read.md\nWrite your report in parts of five entries: write the first part to the file, then add each next part to its end, one tool call for each part. So no reply runs for minutes, and your prompt cache stays warm between your calls.`, { label: 'cold read', phase: 'Check', ...OPUS }),
])

phase('Fix')
const w2 = await drive(2)

phase('Judge')
const j = await agent(`Read your brief and follow it: ${T}judge.md\n\n${where}`, { label: 'judge', phase: 'Judge', ...OPUS })
log(`judged: ${cut(j, 200)}`)

const result = {
  batch: N, worktree: WT, branch: BRANCH, run: RUN, diff: RUN + 'diff.md',
  sort: { counts: s.counts, orientation: s.orientation, curator: s.curator, summary: cut(s.summary, 1200) },
  write: cut(w1, 1500), checks: checks.map(c => cut(c, 800)), fix: cut(w2, 1500), judge: cut(j, 2000),
}
if (args.at) return result   // a replay lands nothing on main
if (!j) return Object.assign(result, { stopped: 'the judge returned nothing: nothing landed; read its transcript and the run folder before a resume' })

// The landing (curator, 2026-11-03 06:2x, HELD.md): the commits go onto main in this run, and the orientation
// update follows in the same chain. A fast-forward keeps the judge's hashes when main has not moved since AT; a
// cherry-pick lands the same two commits when it has. The judge's diff.md, "Next", gives the update's entries.
  '',
  'Return the structured result: commits as "hash subject" from git log --format="%h %s" mainBefore..main.',
].join('\n'), { label: 'land', phase: 'Land', ...SONNET, schema: LAND })
result.land = l
if (!l || !l.landed) return Object.assign(result, { stopped: 'nothing landed: ' + (l ? l.stopped : 'the lander returned nothing; read its transcript, git -C ' + MAIN + ' log origin/main..main and the branch before a resume') })
if (l.stopped) return Object.assign(result, { stopped: 'landed on the local main, not all pushed, no orientation update: ' + l.stopped })

// The orientation update, the child workflow (one level deep), on the entries diff.md's "Next" names. With no
// entry there, the update has nothing to judge, and the skill update below still runs on diff.md's skill lines.
const facts = (l.facts || []).filter(f => /^[FP]-\d+$/.test(f))
log('landed by ' + l.how + ': ' + l.commits.join('; ') + (facts.length ? '; the orientation update on ' + facts.join(', ') : '; diff.md, "Next", names no entry for the orientation update'))
if (facts.length) {
  try {
    result.orientation = await workflow({ scriptPath: '/home/user/fortress/explorations/coordinator/tools/orientation/orientation.js' },
      { mode: 'update', out: '/home/user/fortress/explorations/compile-ladder/climb-batch-' + N + '/orientation/', stream: 'orientation-b' + N, facts })
  } catch (e) {
    return Object.assign(result, { stopped: 'landed and pushed; the orientation update failed to start, and no skill update ran: ' + e.message })
  }
} else {
  result.orientation = { skipped: 'diff.md, "Next", names no entry' }
}

// The skill update (the coordinator skill's batch.md, "The landing", step 4, and skill-rewrite.md, "The method",

// workflow-scenarios.js [SCRIPT] [--sizes RUN_DIR] [--dump DIR] [--skill SKILL_DIR]
//
// The scenario checker of the batch workflow script, explorations/coordinator/climb-batch-workflow.js
// (its manual: explorations/coordinator/climb-batch-workflow.md; the practice it builds:
// explorations/coordinator/process-engineering/batch-redesign.md). SCRIPT defaults to the working copy.
// Nothing is launched and nothing is built: the script runs as the Workflow harness runs it, its text with
// "export const meta" made "const meta" as the body of an async function, its globals (args, agent,
// pipeline, parallel, log) stubbed, once per scenario; each run's agents, in the order they are called,
// and its result are compared with what the scenario expects. Its last line counts the problems; exit 1 if
// any.
//
// Before the runs: node --check, and the harness's parse (FACTS.md, "node --check does not check the batch
// script as the Workflow harness parses it ..."); no backtick and no non-ASCII character; the gate's shell
// functions file, tools/gate-functions.sh, parsed by bash and defining its three functions. The scenarios name rungs by their place in the manifest the script carries (R0 is the first
// rung of RUNGS, R1 the second; S0 the first in the scatter's order), so they run on any batch's block of
// the redesigned form.
//
// The scenarios (rewritten for the redesign of 2026-10-08; the earlier checker's are in git at
// cd2393a08): every agent approving; a skeptic that fixes and approves (no judge); a fix contested and
// upheld, contested and repaired, a refusal ruled to stand, repaired, dropped; a worker that stops; a rung withheld
// where a scenario drops or stops a rung it lands only with (landsOnlyWith), nothing gathered if none is left; the
// merged tree's paths carried over from the earlier checker (the review routing, a code finding repaired
// with and without a second gate, a red gate and its repair, a review that returns nothing, the judge's
// land, the paths no gate stage reads); the push held by a step that cannot be undone and not by a
// reversible point, nor by a point against a decision that the review's repair settled with its evidence (climb
// batch 27's demo), but by one marked as one that cannot be undone or settled with no evidence; the disk under its
// floor, or no reading of it, stopping the run before the scatter; no skill text written and no cold read in any run (the batch's revival-change material
// goes into its RECORD.md for the skill writer: reviews/skills-agenda-audit.md), a path under .claude/ that
// changed listed as skill-touched, and a gather's stray deltaEntries routed nowhere; the commit stage's checks of
// footers and .claude/ over the batch's own commits, from the gather's headBefore, and from the base only where the
// gather gave none, and no item of a path outside .claude/; a reserved point the gather listed in RECORD.md listed
// for the curator; after a repair of tests only that its runs do not answer for, the gate's stages that read those files
// again (testFast, testSystem, the atomic runs) and the whole gate where a red line names no file it changed, a
// red stage-only run stopping the batch; testSpecData in the gate
// when the rung that brings it lands, and not when it is dropped; the stops on a usage limit and the resumes.
// And in every scenario, each brief: no undefined, NaN or object rendered; the head and the skill named; the
// skill's revival-changes part named by none; the worker's "Revival change" section in its two labelled parts,
// the gather's copy of it into RECORD.md, the review's check of it, the commit stage's check of .claude/; the
// gather's record of the HEAD it starts from, its historical: lines from its staged diff, its reserved points; no
// global.map restore, no copy of the base, no one-thread pin, no
// stopsMet, no run_bg (the permission check refuses it; the literal nohup form instead), no person named but
// in PLAN.md's heading; the worker's seed command; the skeptic's old-code tool, journal command and "You
// build nothing to check"; no skeptic brief carrying the worker's report text; the commit's one atomic push of
// the three refs, its retry the same command whole (C6), and the quick microGPT check; a merged-tree repair's
// build of the specification kept, and taken by the commit stage only from a repair that landed (D5, D6).
//
// With --sizes RUN_DIR (a batch run's directory, journal.jsonl and agent transcripts beside it, such as
// climb batch 10's): renders every role's brief with that run's real agent results as the stubs' returns
// (mapped onto the script's rungs in order, their fields renamed to the redesign's), and prints each brief's
// size in characters beside that run's own first message of the same role, and the first call's tokens by
// the fit of process-engineering/checking-roles-cost.md (41.7K + 0.425 tokens a character of brief).
const fs = require('fs')
const path = require('path')
const cp = require('child_process')
const crypto = require('crypto')

const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../..')
const argv = process.argv.slice(2)
const sizesAt = argv.indexOf('--sizes'), dumpAt = argv.indexOf('--dump'), skillAt = argv.indexOf('--skill')
const SIZES_DIR = sizesAt >= 0 ? argv[sizesAt + 1] : null
const DUMP_DIR = dumpAt >= 0 ? argv[dumpAt + 1] : null   // writes every brief of every scenario there, one file each, for reading
const SKILL_DIR = skillAt >= 0 ? argv[skillAt + 1] : path.join(ROOT, '.claude/skills/fortress-repo')   // the skill whose sections the script cites
const valued = new Set([sizesAt, dumpAt, skillAt].filter(i => i >= 0).map(i => i + 1))
const target = argv.filter((a, i) => !/^--(sizes|dump|skill)$/.test(a) && !valued.has(i))[0] || path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const BASE_BUILD = '/home/user/fortress-base'
const orig = fs.readFileSync(target, 'utf8')

let bad = 0
const say = (ok, line) => { if (!ok) bad++; console.log((ok ? 'ok   ' : 'BAD  ') + line) }
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
{
  const r = cp.spawnSync('node', ['--check', target], { encoding: 'utf8' })
  say(r.status === 0, 'node --check: exit ' + r.status + (r.stderr.trim() ? ' ' + r.stderr.trim().slice(0, 300) : ''))
  let err = null
  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', orig.replace(/^export const meta/m, 'const meta')) } catch (e) { err = e }
  say(!err, 'the harness\'s parse: ' + (err ? 'refused, ' + err.message : 'accepted as an async function body, its export made const'))
  const ticks = orig.match(/\x60/g) || []
  say(!ticks.length && !/[^\x00-\x7f]/.test(orig), 'the script holds ' + ticks.length + ' backtick(s) and ' + ((orig.match(/[^\x00-\x7f]/g) || []).length) + ' non-ASCII character(s)')
  const GATE_FNS = ['gate_summary', 'gate_compare', 'last_landed_summary']
